import{_ as o,c as a,o as t,ag as r}from"./chunks/framework.B-XtCDNB.js";const p=JSON.parse('{"title":"3.5. Flow Analyzer","description":"3.5. Flow Analyzer Vala.FlowAnalyzer is a CodeVisitor that checks that checks for the validity of the control flow logic of the source code. This is focused on whether the rules of the different...","frontmatter":{"prev":{"text":"3.4. Semantic Analyzer","link":"/guides/compiler-guide/03-00-the-vala-compiler/03-04-semantic-analyzer"},"next":{"text":"3.6. C Code Generation","link":"/guides/compiler-guide/03-00-the-vala-compiler/03-06-c-code-generation"}},"headers":[],"relativePath":"guides/compiler-guide/03-00-the-vala-compiler/03-05-flow-analyzer.md","filePath":"guides/compiler-guide/03-00-the-vala-compiler/03-05-flow-analyzer.md","lastUpdated":1786057156000}'),l={name:"guides/compiler-guide/03-00-the-vala-compiler/03-05-flow-analyzer.md"};function i(n,e,c,d,s,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-5-flow-analyzer" tabindex="-1">3.5. Flow Analyzer <a class="header-anchor" href="#_3-5-flow-analyzer" aria-label="Permalink to &quot;3.5. Flow Analyzer&quot;">​</a></h1><p><code>Vala.FlowAnalyzer</code> is a <code>CodeVisitor</code> that checks that checks for the validity of the control flow logic of the source code.</p><p>This is focused on whether the rules of the different blocks and control flow blocks (if-statements, switch statements etc.) are being followed correctly in the source code. As well as providing warnings about potential unexpected behaviour like a local variable being declared but never used in a block.</p><h2 id="_3-5-1-how-it-works" tabindex="-1">3.5.1 How It Works <a class="header-anchor" href="#_3-5-1-how-it-works" aria-label="Permalink to &quot;3.5.1 How It Works&quot;">​</a></h2><p>In <code>Vala.FlowAnalyzer.analyze ()</code>, the flow analyzer loops through each source file available in the <code>Vala.CodeContext</code> calls <code>Vala.SourceFile.accept ()</code> on each of them, recursively going through the symbol tree to builds a control flow graph.</p><p>Like in <code>Vala.Parser</code> there are <code>vist_</code> method overrides. These overrides contain the logic for checking the validity of the control flow related code between blocks, control flow blocks and related statements.</p><h2 id="_3-5-2-error-handling" tabindex="-1">3.5.2 Error Handling <a class="header-anchor" href="#_3-5-2-error-handling" aria-label="Permalink to &quot;3.5.2 Error Handling&quot;">​</a></h2><p>If any errors have been reported, after the flow analyzer has finishing building a control flow graph, the compiler program will exit early and not proceed to the next stage.</p>',8)])])}const u=o(l,[["render",i]]);export{p as __pageData,u as default};
